INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (11, '温斯顿·丘吉尔', 'Winston Churchill', '1874—1965', '19—20世纪', '英国', '首相', ARRAY['政治家', '英国', '二战'], '英国首相，二战期间领导英国抵抗纳粹。他以雄辩演说鼓舞国民，战后获诺贝尔文学奖，是20世纪最具辨识度的政治家之一。', '房东', '', 'assets/figures/churchill.jpg', ARRAY['11-30', '05-08'], ARRAY['诞辰 · 1874年11月30日', '欧洲胜利日 · 1945年5月8日'], ARRAY['birth', 'event'], '他在最坏的时候租下你的房子，也在这里收到过最好的消息。', ARRAY['房东', '战地记者'], ARRAY['他在最坏的时候租下你的房子，也在这里收到过最好的消息。', '年轻时他当过战地记者，和你挤同一节火车厢，稿子你帮着抄。']),
  (12, '尼禄', 'Nero', '37—68', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '暴君'], '罗马皇帝，朱里亚·克劳狄王朝末代君主。他以残暴与挥霍著称，却也是个热衷赛车的表演者，最后在政变中亡命。', '乐评人', '', 'assets/figures/nero.jpg', ARRAY['12-15', '06-19'], ARRAY['诞辰 · 37年12月15日', '罗马大火 · 64年6月19日'], ARRAY['birth', 'event'], '他写的歌当场被人嘘过，而这些评价他全都留了下来。', ARRAY['乐评人', '御用替身'], ARRAY['他写的歌当场被人嘘过，而这些评价他全都留了下来。', '他在舞台上从不让人靠近，唯独你替他挡过一次飞来的番茄。']),
  (13, '哥白尼', 'Nicolaus Copernicus', '1473—1543', '文艺复兴', '波兰', '天文学家', ARRAY['科学家', '波兰', '天文'], '波兰天文学家，日心说的提出者。他在《天体运行论》中颠覆了千年的地心观念，开启了科学革命。', '望远镜推销员', '', 'assets/figures/copernicus.jpg', ARRAY['02-19', '05-24'], ARRAY['诞辰 · 1473年2月19日', '《天体运行论》出版 · 1543年5月24日'], ARRAY['birth', 'event'], '他把地球挪到了太阳旁边，卖了几百年也没卖出几本。', ARRAY['望远镜推销员', '主教座堂乐师'], ARRAY['他把地球挪到了太阳旁边，卖了几百年也没卖出几本。', '他本职是教堂的教士兼乐师，管风琴旁边常站着旁听的你。']),
  (14, '伽利略·伽利莱', 'Galileo Galilei', '1564—1642', '文艺复兴', '意大利', '天文学家', ARRAY['科学家', '意大利', '天文'], '意大利天文学家与物理学家，望远镜天文观测的先驱。他支持日心说，以观测证据挑战教会权威，被视为近代科学之父。', '科学期刊主编', '', 'assets/figures/galileo.jpg', ARRAY['02-15', '01-07'], ARRAY['诞辰 · 1564年2月15日', '发现木星卫星 · 1610年1月7日'], ARRAY['birth', 'event'], '他证明了地球在动，而刊出这件事的那本期刊，是你的。', ARRAY['科学期刊主编', '观星搭档'], ARRAY['他证明了地球在动，而刊出这件事的那本期刊，是你的。', '他每夜对着镜片数卫星，递咖啡、记时辰的那个人是你。']),
  (15, '艾萨克·牛顿', 'Isaac Newton', '1643—1727', '17—18世纪', '英国', '物理学家', ARRAY['科学家', '英国', '物理'], '英国物理学家、数学家，经典力学的奠基者。他的《自然哲学的数学原理》以万有引力与三大定律统一了天与地。', '望远镜推销员', '', 'assets/figures/newton.jpg', ARRAY['12-25', '07-05'], ARRAY['诞辰 · 1642年12月25日', '《原理》出版 · 1687年7月5日'], ARRAY['birth', 'event'], '他磨了十年镜片才磨出一点弧度，只为看清那道土星环。', ARRAY['望远镜推销员', '造币厂学徒'], ARRAY['他磨了十年镜片才磨出一点弧度，只为看清那道土星环。', '晚年他主管皇家造币厂，熔金铸币的炉边常站着帮手的你。']),
  (16, '查尔斯·达尔文', 'Charles Darwin', '1809—1882', '19世纪', '英国', '博物学家', ARRAY['科学家', '英国', '生物'], '英国博物学家，进化论的奠基者。他乘贝格尔号环球考察，以《物种起源》提出自然选择，重塑了人类对自身的认识。', '标本管理员', '', 'assets/figures/darwin.jpg', ARRAY['02-12', '11-24'], ARRAY['诞辰 · 1809年2月12日', '《物种起源》出版 · 1859年11月24日'], ARRAY['birth', 'event'], '他收集的每一只雀嘴，最后都变成了关于人类的结论。', ARRAY['标本管理员', '随船博物学家'], ARRAY['他收集的每一只雀嘴，最后都变成了关于人类的结论。', '贝格尔号启航那天，舱里那一箱标本的清单是你帮他核的。']),
  (17, '路易·巴斯德', 'Louis Pasteur', '1822—1895', '19世纪', '法国', '微生物学家', ARRAY['科学家', '法国', '医学'], '法国微生物学家与化学家，巴氏杀菌与疫苗接种的先驱。他证明了微生物致病，奠定了现代免疫学与公共卫生。', '兽医助手', '', 'assets/figures/pasteur.jpg', ARRAY['12-27', '07-06'], ARRAY['诞辰 · 1822年12月27日', '狂犬病疫苗 · 1885年7月6日'], ARRAY['birth', 'event'], '他给牛羊做实验，也给自己接种疫苗——这是他实验室的第一条规矩。', ARRAY['兽医助手', '葡萄酒师'], ARRAY['他给牛羊做实验，也给自己接种疫苗——这是他实验室的第一条规矩。', '他帮酒农保住葡萄酒，去酒庄取样的马车里总坐着你。']),
  (18, '尼古拉·特斯拉', 'Nikola Tesla', '1856—1943', '19—20世纪', '美国', '电气工程师', ARRAY['科学家', '美国', '电气'], '塞尔维亚裔美籍发明家与电气工程师，交流电系统的奠基者。他在无线传输与电机领域拥有数百项专利。', '专利代理人', '', 'assets/figures/tesla.jpg', ARRAY['07-10', '05-16'], ARRAY['诞辰 · 1856年7月10日', '西屋电灯博览会 · 1893年5月16日'], ARRAY['birth', 'event'], '他点亮了大半个世界的电流，专利簿上写的却是别人的名字。', ARRAY['专利代理人', '旅馆房客'], ARRAY['他点亮了大半个世界的电流，专利簿上写的却是别人的名字。', '他晚年住在旅馆，账单一半是你替他担保垫付的。']),
  (19, '玛丽·居里', 'Marie Curie', '1867—1934', '19—20世纪', '法国', '物理学家', ARRAY['科学家', '波兰', '化学'], '波兰裔法国物理学家与化学家，放射性研究的先驱。她是首位获诺贝尔奖的女性，也是唯一两获诺奖且分属两科的科学家。', '实验搭档', '', 'assets/figures/curie.jpg', ARRAY['11-07', '12-10'], ARRAY['诞辰 · 1867年11月7日', '诺贝尔奖颁奖 · 1903年12月10日'], ARRAY['birth', 'event'], '两次诺贝尔奖背后，站着一个长期被低估的合作者。', ARRAY['实验搭档', '矿场采样员'], ARRAY['两次诺贝尔奖背后，站着一个长期被低估的合作者。', '她去矿上采沥青铀矿，陪她钻巷道、扛麻袋的是你。']),
  (20, '阿尔伯特·爱因斯坦', 'Albert Einstein', '1879—1955', '19—20世纪', '美国', '物理学家', ARRAY['科学家', '德国', '物理'], '理论物理学家，相对论的创立者。他重新定义了时间、空间与引力，是现代物理学的象征性人物。', '同事', '', 'assets/figures/einstein.jpg', ARRAY['03-14', '06-30'], ARRAY['诞辰 · 1879年3月14日', '奇迹年 · 1905年6月30日'], ARRAY['birth', 'event'], '相对论诞生在专利局的办公室里，同事们只当他是个爱讲笑话的人。', ARRAY['同事', '小提琴搭档'], ARRAY['相对论诞生在专利局的办公室里，同事们只当他是个爱讲笑话的人。', '他拉小提琴时总缺个能跟上的搭档，那个人是你。'])
